ALTER TABLE projects ADD COLUMN operational_state TEXT NOT NULL DEFAULT 'open' CHECK(operational_state IN('open','completed'));
ALTER TABLE bills ADD COLUMN due_date TEXT;
ALTER TABLE requests ADD COLUMN kind TEXT NOT NULL DEFAULT 'purchase' CHECK(kind IN('purchase','advance'));
ALTER TABLE commitments ADD COLUMN effective_date TEXT;
DROP TRIGGER IF EXISTS immutable_commitments_UPDATE;
UPDATE commitments SET effective_date=COALESCE((SELECT date FROM journals WHERE journals.id=commitments.journal_id),CASE WHEN reason='Approved spending reservation' THEN (SELECT r.date FROM request_lines l JOIN requests r ON r.id=l.request_id WHERE l.id=commitments.request_line_id) ELSE substr(created_at,1,10) END);
CREATE TABLE budget_changes(budget_id INTEGER PRIMARY KEY REFERENCES budget_versions(id),kind TEXT NOT NULL,details TEXT NOT NULL);
CREATE TABLE advance_requests(request_id INTEGER PRIMARY KEY REFERENCES requests(id),beneficiary TEXT NOT NULL,beneficiary_type TEXT NOT NULL CHECK(beneficiary_type IN('employee','supplier')),due_date TEXT NOT NULL);
CREATE TABLE advance_terms(advance_id INTEGER PRIMARY KEY REFERENCES advances(id),beneficiary_type TEXT NOT NULL CHECK(beneficiary_type IN('employee','supplier')),due_date TEXT NOT NULL);
CREATE TABLE documents(id INTEGER PRIMARY KEY,kind TEXT NOT NULL,entity_id INTEGER NOT NULL,projects TEXT NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>0 AND bytes<=524288),sha256 TEXT NOT NULL,content BLOB NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE credit_notes(id INTEGER PRIMARY KEY,bill_id INTEGER NOT NULL REFERENCES bills(id),reference TEXT NOT NULL UNIQUE,journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id),date TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE credit_lines(id INTEGER PRIMARY KEY,credit_id INTEGER NOT NULL REFERENCES credit_notes(id),bill_line_id INTEGER NOT NULL REFERENCES bill_lines(id),amount INTEGER NOT NULL CHECK(amount>0),liability_amount INTEGER NOT NULL CHECK(liability_amount>=0),receivable_amount INTEGER NOT NULL CHECK(receivable_amount>=0),restore_commitment INTEGER NOT NULL CHECK(restore_commitment IN(0,1)),CHECK(amount=liability_amount+receivable_amount));
CREATE TABLE supplier_refunds(id INTEGER PRIMARY KEY,credit_id INTEGER NOT NULL REFERENCES credit_notes(id),account_id INTEGER NOT NULL REFERENCES accounts(id),reference TEXT NOT NULL,journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id),amount INTEGER NOT NULL CHECK(amount>0),UNIQUE(account_id,reference));
CREATE TABLE refund_lines(id INTEGER PRIMARY KEY,refund_id INTEGER NOT NULL REFERENCES supplier_refunds(id),credit_line_id INTEGER NOT NULL REFERENCES credit_lines(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE promise_adjustments(id INTEGER PRIMARY KEY,promise_id INTEGER NOT NULL REFERENCES promises(id),amount INTEGER NOT NULL CHECK(amount<0),reference TEXT NOT NULL UNIQUE,date TEXT NOT NULL,reason TEXT NOT NULL);
CREATE TABLE correction_authorizations(id INTEGER PRIMARY KEY,journal_id INTEGER NOT NULL REFERENCES journals(id),poster_id INTEGER NOT NULL REFERENCES users(id),actor_id INTEGER NOT NULL REFERENCES users(id),expiry TEXT NOT NULL,reason TEXT NOT NULL,CHECK(poster_id<>actor_id));
CREATE TABLE correction_uses(authorization_id INTEGER PRIMARY KEY REFERENCES correction_authorizations(id),journal_id INTEGER NOT NULL UNIQUE REFERENCES journals(id));
CREATE TABLE statements(id INTEGER PRIMARY KEY,account_id INTEGER NOT NULL REFERENCES accounts(id),reference TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,opening_balance INTEGER NOT NULL,closing_balance INTEGER NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(account_id,reference),CHECK(start_date<=end_date));
CREATE TABLE statement_lines(id INTEGER PRIMARY KEY,statement_id INTEGER NOT NULL REFERENCES statements(id),account_id INTEGER NOT NULL REFERENCES accounts(id),external_id TEXT NOT NULL,date TEXT NOT NULL,description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount<>0),UNIQUE(account_id,external_id));
CREATE TABLE statement_matches(id INTEGER PRIMARY KEY,statement_line_id INTEGER NOT NULL REFERENCES statement_lines(id),journal_line_id INTEGER NOT NULL REFERENCES journal_lines(id),amount INTEGER NOT NULL CHECK(amount>0),reference TEXT NOT NULL UNIQUE,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE match_reversals(match_id INTEGER PRIMARY KEY REFERENCES statement_matches(id),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE statement_events(id INTEGER PRIMARY KEY,statement_id INTEGER NOT NULL REFERENCES statements(id),kind TEXT NOT NULL CHECK(kind IN('finalize','reopen')),reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),line_watermark INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE statement_reviews(id INTEGER PRIMARY KEY,event_id INTEGER NOT NULL REFERENCES statement_events(id),journal_line_id INTEGER NOT NULL REFERENCES journal_lines(id),amount INTEGER NOT NULL,reason TEXT NOT NULL);
CREATE TABLE cash_offsets(id INTEGER PRIMARY KEY,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cash_offset_lines(journal_line_id INTEGER PRIMARY KEY REFERENCES journal_lines(id),offset_id INTEGER NOT NULL REFERENCES cash_offsets(id),amount INTEGER NOT NULL CHECK(amount>0));
CREATE TABLE project_events(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),kind TEXT NOT NULL,reason TEXT NOT NULL,actor_id INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE closure_authorizations(id INTEGER PRIMARY KEY,project_id INTEGER NOT NULL REFERENCES projects(id),closer_id INTEGER NOT NULL REFERENCES users(id),actor_id INTEGER NOT NULL REFERENCES users(id),expiry TEXT NOT NULL,reason TEXT NOT NULL,fingerprint TEXT NOT NULL,treatments TEXT NOT NULL,CHECK(closer_id<>actor_id));
CREATE TABLE closure_uses(authorization_id INTEGER PRIMARY KEY REFERENCES closure_authorizations(id),event_id INTEGER NOT NULL UNIQUE REFERENCES project_events(id));
INSERT INTO accounts(code,name,type) VALUES('1300','Supplier refund receivables','asset');
CREATE INDEX match_book ON statement_matches(journal_line_id);
CREATE INDEX match_statement ON statement_matches(statement_line_id);
CREATE INDEX document_entity ON documents(kind,entity_id);
